diff --git a/parallel_help_repro_test.go b/parallel_help_repro_test.go
new file mode 100644
index 0000000..37f482d
--- /dev/null
+++ b/parallel_help_repro_test.go
@@ -0,0 +1,122 @@
+package cli_test
+
+import (
+	"context"
+	"fmt"
+	"sync"
+	"sync/atomic"
+	"testing"
+
+	"github.com/urfave/cli/v3"
+)
+
+func runCliParallelHelp(args []string) {
+	runCliParallelHelpWith(args, false)
+}
+
+func runCliParallelHelpWith(args []string, hideHelp bool) {
+	cmd := &cli.Command{
+		Name:     "debug",
+		Usage:    "make an explosive entrance",
+		HideHelp: hideHelp,
+		Action: func(_ context.Context, cmd *cli.Command) error {
+			return nil
+		},
+	}
+
+	if err := cmd.Run(context.Background(), args); err != nil {
+		fmt.Printf("%s\n", err)
+	}
+}
+
+type parallelHelpCase struct {
+	Name string
+	Args []string
+	Exit int
+}
+
+// Test_run is the reporter's test (urfave/cli HelpFlag global shared across
+// parallel Command.Run calls), unchanged apart from names.
+func Test_run(t *testing.T) {
+	t.Parallel()
+
+	tests := []parallelHelpCase{
+		{
+			Name: "hello_world",
+			Exit: 0,
+		},
+		{
+			Name: "hello_sunshine",
+			Exit: 0,
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.Name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					t.Errorf("unexpected panic - '%s' passing %s", r, tt.Args)
+				}
+			}()
+
+			runCliParallelHelp(tt.Args)
+		})
+	}
+}
+
+// Test_runStress is the same scenario as Test_run (many independent
+// Commands with default HideHelp=false, each Run once, concurrently), but with
+// enough goroutines and iterations that the nil pointer dereference from the
+// report is hit essentially every time instead of about once per ~300k runs.
+func Test_runStress(t *testing.T) {
+	stressParallelRun(t, false)
+}
+
+// Test_runStressHideHelp is the report's workaround (HideHelp set) under the
+// identical load; it is only here to show the stress check can pass.
+func Test_runStressHideHelp(t *testing.T) {
+	stressParallelRun(t, true)
+}
+
+func stressParallelRun(t *testing.T, hideHelp bool) {
+	t.Helper()
+
+	const (
+		goroutines = 32
+		iterations = 20000
+	)
+
+	var (
+		wg     sync.WaitGroup
+		panics atomic.Int64
+		first  atomic.Value
+		start  = make(chan struct{})
+	)
+
+	for g := 0; g < goroutines; g++ {
+		wg.Add(1)
+		go func() {
+			defer wg.Done()
+			<-start
+			for i := 0; i < iterations && panics.Load() == 0; i++ {
+				func() {
+					defer func() {
+						if r := recover(); r != nil {
+							panics.Add(1)
+							first.CompareAndSwap(nil, fmt.Sprint(r))
+						}
+					}()
+					runCliParallelHelpWith(nil, hideHelp)
+				}()
+			}
+		}()
+	}
+
+	close(start)
+	wg.Wait()
+
+	if panics.Load() != 0 {
+		t.Fatalf("unexpected panic running cli.Command in parallel: %v", first.Load())
+	}
+}
